CREATE TABLE public.card_authorizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, booking_id uuid NOT NULL REFERENCES public.bookings(id), amount_cents integer NOT NULL CHECK(amount_cents>0), terms_version text NOT NULL DEFAULT 'appointment-balance-v1', terms_text text NOT NULL, authorized_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz, UNIQUE(booking_id,user_id));
GRANT SELECT ON public.card_authorizations TO authenticated; GRANT ALL ON public.card_authorizations TO service_role;
ALTER TABLE public.card_authorizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner or admin reads authorization" ON public.card_authorizations FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.portal_charge_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id), user_id uuid NOT NULL, authorization_id uuid NOT NULL REFERENCES public.card_authorizations(id), requested_by uuid NOT NULL, amount_cents integer NOT NULL CHECK(amount_cents>0), service_amount_cents integer NOT NULL CHECK(service_amount_cents>0), status text NOT NULL DEFAULT 'reserved', stripe_payment_intent_id text UNIQUE, receipt_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portal_charge_requests TO authenticated; GRANT ALL ON public.portal_charge_requests TO service_role;
ALTER TABLE public.portal_charge_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner or admin reads charge" ON public.portal_charge_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin());
CREATE TABLE public.customer_service_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id), note text NOT NULL CHECK(length(note) BETWEEN 1 AND 4000), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.customer_service_notes TO authenticated; GRANT ALL ON public.customer_service_notes TO service_role;
ALTER TABLE public.customer_service_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owners read published service notes" ON public.customer_service_notes FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.bookings b WHERE b.id=booking_id AND b.user_id=auth.uid()) OR public.is_admin());
CREATE POLICY "Admins publish service notes" ON public.customer_service_notes FOR ALL TO authenticated USING(public.is_admin()) WITH CHECK(public.is_admin() AND created_by=auth.uid());
CREATE TABLE public.customer_notification_preferences(user_id uuid PRIMARY KEY, email_reminders boolean NOT NULL DEFAULT false, sms_reminders boolean NOT NULL DEFAULT false, marketing_emails boolean NOT NULL DEFAULT false, consent_version text NOT NULL DEFAULT 'portal-reminders-v1', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.customer_notification_preferences TO authenticated; GRANT ALL ON public.customer_notification_preferences TO service_role;
ALTER TABLE public.customer_notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads preferences" ON public.customer_notification_preferences FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Owner adds preferences" ON public.customer_notification_preferences FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY "Owner updates preferences" ON public.customer_notification_preferences FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
ALTER TABLE public.payment_records ADD COLUMN IF NOT EXISTS receipt_url text;
ALTER TABLE public.bookings ADD COLUMN IF NOT EXISTS reminder_email_consent boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS reminder_sms_consent boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS reminder_consent_at timestamptz;
CREATE TABLE public.sms_opt_outs(phone text PRIMARY KEY, opted_out_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.sms_opt_outs TO service_role;
ALTER TABLE public.sms_opt_outs ENABLE ROW LEVEL SECURITY;